/*
# Testing module — seed real catalog data (chunk 4/6)

Upserts the actual test-case catalog (ADMIN-MGMT remaining, ADMIN-SETTINGS, ADMIN-LOG,
NOTIF, OFFLINE, I18N, DB modules, cases 180–239 of 302). ON CONFLICT upserts — safe to
re-run, nothing deleted.
*/

ON CONFLICT (test_case_id) DO UPDATE SET
module_code=EXCLUDED.module_code, title=EXCLUDED.title, priority=EXCLUDED.priority,
description=EXCLUDED.description, feature=EXCLUDED.feature, sort_order=EXCLUDED.sort_order;